// points to interpolate, don't put them too far as I didn't implement the "blub" edge cases
vec2 from = vec2(0., 0.);
vec2 to = vec2(292., 154.);

vec2 posFromViewport(vec2 uv, vec3 viewport) {
    // adjust values to match the isbn scaling
    return viewport.xy/150. + (uv - .5) * viewport.z*10.;
}


float baseZoom = 1./14000.;
vec3 hyperbola(vec2 from, vec2 to, float t) {
    vec2 center = (from + to)/2.;
    // the 800 can be tuned, it weights the velocity of zooming vs panning (and accounts for viewport size)
    float zoomScale = distance(center, from)/800.;
    float baseAngle = baseZoom/zoomScale; // small angle
    float v = pow(2./baseAngle, 2.*t - 1.); // small angle again for ln(csc-cot)
    return vec3(mix(to, from, 1./(1.+v*v)), zoomScale*2.*v/(1.+v*v));
}

// the blub motion has speed depending on zoom, which for book-to-book paths would work out
// to some complicated easing which i'm not going to match here
float ease(float t) {
    float base = 0.;
    float mul = 1.;
    if (t > .5) {
        base = 1.;
        mul = -1.;
        t = 1. - t;
    }
    return base + mul*(.5 * pow(2.*t, 6.));
}

vec3 blub(vec2 from, vec2 to, float t) {
    vec2 bfrom = vec2(2.1 - baseZoom, 0.);
    float angle = 3.14159*distance(from,to)/500.; // "segment length" in original
    vec2 bto = (2.1 - baseZoom)*vec2(cos(angle),sin(angle));
    vec2 bcurr = mix(bfrom, bto, ease(t));
    return vec3(mix(from, to, atan(bcurr.y, bcurr.x)/angle), 2.1-length(bcurr));
}

float hash(int level, ivec2 value) {
    int q = value.x*5 + value.y*53;
    int n = (1 << 17) ^ q;
    n = (level + 1) * n * (n * n *986 + 12347) + 0x003455;
    return float(n & 0x00ffffff)/float(0x00ffffff);
}

vec2 baseRect = vec2(1., sqrt(10.));
// simple mockup of book layout
vec3 bookColor(vec2 pos) {
    float sizeCutoff = 1.-log(abs(dFdx(pos.x)))/log(10.);
    int iters = min(5, int(sizeCutoff));
    int i;
    float density = .8;
    float last = 1.;

    for (i = 0; i < iters; i++) {
        vec2 rel = floor(pos/baseRect);
        if (i == 0) {
            if (abs(rel.x+.5) > 5. || abs(rel.y+.5) > 1.)
                return vec3(0.);
        }
        last = hash(i, ivec2(rel));
        if (last > density)
            return vec3(0.);
        density = pow(last/density, .5);
        pos = pos*10.;
    }
    if (sizeCutoff > 6.) {
        vec2 rel = vec2(1.4, 1.2+.1*last)*(mod(pos/10., baseRect)/baseRect - .5);
        if (rel.x < -.5 || max(rel.x, rel.y) > .5)
            return vec3(0.);
        density *= 1.5;
    }
    return vec3(density, 0., 0.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 uv = fragCoord/iResolution.xy;

    float t = mod(iTime-.5, 15.);
    vec3 viewport;
    if (t < 7.5) {
        viewport = blub(from, to, clamp(t/7., 0., 1.));
    } else {
        viewport = hyperbola(to, from, clamp((t-7.5)/7., 0., 1.));
    }
    fragColor = vec4(bookColor(posFromViewport(uv, viewport)),1.0);
}
